Fórmula anterior (invariante):
If(
    IsBlank(locAv.Uid), Notify("Avaliação não encontrada.", NotificationType.Error),
    locAv.Estado <> "PREENCHIMENTO" || locAv.Avaliador <> varUsuario.Codigo, Notify("Somente o avaliador responsável pode salvar uma avaliação em preenchimento.", NotificationType.Error),
    UpdateContext({locProcAva: true});
    With({_json: JSON({pessoaNome: Coalesce(locAv.PessoaNomeSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Nome), cargo: Coalesce(locAv.CargoSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Cargo), grupo: Coalesce(locAv.GrupoSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Grupo), perfil: Coalesce(locAv.PerfilSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Perfil), metodo: locAv.MetodoSnap, versao: locAv.VersaoSnap, criterios: ForAll(colCritAva, {criterioId: Id, dimensao: Dimensao, descricao: Descricao, evidenciaEsperada: Evidencia, permiteNA: PermiteNA, condicaoNA: CondicaoNA, areas: Areas, fontes: Fontes, modo: Modo, resposta: Resposta, comentario: Comentario})}, JSONFormat.Compact)},
        IfError(
            Patch(SGC_Avaliacoes, LookUp(SGC_Avaliacoes, AvaliacaoUid = locAv.Uid), {CriteriosResultadoJson: _json, ParecerTecnico: Trim(txtParecerAva.Text), Observacoes: Trim(txtObsAva.Text)});
            Patch(colAvaliacoes, LookUp(colAvaliacoes, Uid = locAv.Uid), {CriteriosJson: _json, Parecer: Trim(txtParecerAva.Text), Observacoes: Trim(txtObsAva.Text)});
            UpdateContext({locAv: LookUp(colAvaliacoes, Uid = locAv.Uid), locProcAva: false});
            Notify("Rascunho salvo com sucesso.", NotificationType.Success),
            UpdateContext({locProcAva: false}); Notify("Não foi possível salvar o rascunho: " & FirstError.Message, NotificationType.Error)
        )
    )
)

Fórmula nova (invariante):
If(
    IsBlank(locAv.Uid), Notify("Avaliação não encontrada.", NotificationType.Error),
    locAv.Estado <> "PREENCHIMENTO" || locAv.Avaliador <> varUsuario.Codigo, Notify("Somente o avaliador responsável pode salvar uma avaliação em preenchimento.", NotificationType.Error),
    UpdateContext({locProcAva: true});
    With({_json: JSON({pessoaNome: Coalesce(locAv.PessoaNomeSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Nome), cargo: Coalesce(locAv.CargoSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Cargo), grupo: Coalesce(locAv.GrupoSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Grupo), perfil: Coalesce(locAv.PerfilSnap, LookUp(colPessoas, Codigo = locAv.Pessoa).Perfil), metodo: locAv.MetodoSnap, versao: locAv.VersaoSnap, criterios: ForAll(colCritAva, {criterioId: Id, dimensao: Dimensao, descricao: Descricao, evidenciaEsperada: Evidencia, permiteNA: PermiteNA, condicaoNA: CondicaoNA, areas: Areas, fontes: Fontes, modo: Modo, resposta: Resposta, comentario: Comentario})}, JSONFormat.Compact)},
        IfError(
            Patch(SGC_Avaliacoes, LookUp(SGC_Avaliacoes, AvaliacaoUid = locAv.Uid), {CriteriosResultadoJson: _json, ParecerTecnico: Trim(txtParecerAva.Text), Observacoes: Trim(txtObsAva.Text)});
            Patch(colAvaliacoes, LookUp(colAvaliacoes, Uid = locAv.Uid), {CriteriosJson: _json, Parecer: Trim(txtParecerAva.Text), Observacoes: Trim(txtObsAva.Text)});
            UpdateContext({locAv: LookUp(colAvaliacoes, Uid = locAv.Uid), locProcAva: false});
            With({_comentPend: CountRows(Filter(colCritAva, !IsBlank(Resposta) && IsBlank(Trim(Coalesce(Comentario, "")))))}, If(_comentPend = 0, Notify("Rascunho salvo com sucesso.", NotificationType.Success), Notify("Rascunho salvo. Aguardando comentário em " & _comentPend & If(_comentPend = 1, " critério.", " critérios."), NotificationType.Warning))),
            UpdateContext({locProcAva: false}); Notify("Não foi possível salvar o rascunho: " & FirstError.Message, NotificationType.Error)
        )
    )
)
